window.__examData={"exam":"gate","name":"GATE","total":265,"sections":[{"name":"Core Subject","count":114,"questions":[{"id":1772,"text":"The optimum depth of a canal is when:","options":[{"label":"A","text":"Width is minimum"},{"label":"B","text":"Hydraulic radius is maximum"},{"label":"C","text":"Wetted perimeter is maximum"},{"label":"D","text":"Velocity is minimum"}],"answer":1,"solution":"Most economical section: max hydraulic radius → min wetted perimeter."},{"id":1773,"text":"Which flip-flop has no race condition?","options":[{"label":"A","text":"SR"},{"label":"B","text":"JK"},{"label":"C","text":"Master-slave JK"},{"label":"D","text":"D"}],"answer":2,"solution":"Master-slave JK flip-flop eliminates race-around condition."},{"id":1774,"text":"The dry density of soil is maximum at:","options":[{"label":"A","text":"Liquid limit"},{"label":"B","text":"Plastic limit"},{"label":"C","text":"Optimum moisture content"},{"label":"D","text":"Shrinkage limit"}],"answer":2,"solution":"Proctor test: maximum dry density at OMC (optimum moisture content)."},{"id":1775,"text":"If Land ¬L are both recursively enumerable, then L is:","options":[{"label":"A","text":"Regular"},{"label":"B","text":"Context-Free"},{"label":"C","text":"Recursive"},{"label":"D","text":"Not recursively enumerable"}],"answer":2,"solution":"If Land its complement are both RE, then L is recursive (decidable)."},{"id":1776,"text":"In an isothermal process, which quantity remains constant?","options":[{"label":"A","text":"Pressure"},{"label":"B","text":"Volume"},{"label":"C","text":"Temperature"},{"label":"D","text":"Entropy"}],"answer":2,"solution":"Isothermal: T = constant, PV = constant (for ideal gas)."},{"id":1777,"text":"In am in-heap, the smallest element is at:","options":[{"label":"A","text":"Root"},{"label":"B","text":"Leftmost leaf"},{"label":"C","text":"Rightmost leaf"},{"label":"D","text":"Last node"}],"answer":0,"solution":"Min-heap property: parent ≤ children, so root is always the minimum element."},{"id":1778,"text":"The first law of thermodynamics is essentially:","options":[{"label":"A","text":"Conservation of mass"},{"label":"B","text":"Conservation of energy"},{"label":"C","text":"Conservation of momentum"},{"label":"D","text":"Law of entropy"}],"answer":1,"solution":"ΔU = Q - W (energy conservation for thermodynamic systems)."},{"id":1781,"text":"Bernoulli's equation is based on:","options":[{"label":"A","text":"Conservation of mass"},{"label":"B","text":"Conservation of momentum"},{"label":"C","text":"Conservation of energy"},{"label":"D","text":"Continuity"}],"answer":2,"solution":"P/ρg + v²/2g + z = constant (energy per unit weight)."},{"id":1784,"text":"Which language is accepted by Pushdown Automata?","options":[{"label":"A","text":"Regular"},{"label":"B","text":"Context-Free"},{"label":"C","text":"Context-Sensitive"},{"label":"D","text":"Recursively Enumerable"}],"answer":1,"solution":"PDA accepts exactly the class of Context-Free Languages (CFL)."},{"id":1785,"text":"In orthogonal cutting, the cutting edge is:","options":[{"label":"A","text":"Parallel to work surface"},{"label":"B","text":"Perpendicular to cutting velocity"},{"label":"C","text":"At 45°"},{"label":"D","text":"Inclined"}],"answer":1,"solution":"Orthogonal cutting: cutting edge ⊥ to cutting velocity direction."},{"id":1786,"text":"In an RC circuit, the time constant is:","options":[{"label":"A","text":"R + C"},{"label":"B","text":"RC"},{"label":"C","text":"R/C"},{"label":"D","text":"C/R"}],"answer":1,"solution":"τ = RC (time for voltage to reach 63.2% of final value)."},{"id":1788,"text":"The bandwidth of an ideal bandpass filter is:","options":[{"label":"A","text":"Zero"},{"label":"B","text":"Equal to center frequency"},{"label":"C","text":"Difference of cut-off frequencies"},{"label":"D","text":"Infinite"}],"answer":2,"solution":"BW = fH - fL where fH and flare upper and lower cut-off frequencies."},{"id":1789,"text":"The material used for cutting tools is:","options":[{"label":"A","text":"Mild steel"},{"label":"B","text":"HSS (High Speed Steel)"},{"label":"C","text":"Cast iron"},{"label":"D","text":"Brass"}],"answer":1,"solution":"HSS retains hardness at high cutting temperatures (used for drills, end mills)."},{"id":1790,"text":"TIG welding uses which electrode?","options":[{"label":"A","text":"Consumable"},{"label":"B","text":"Non-consumable tungsten"},{"label":"C","text":"Copper"},{"label":"D","text":"Steel"}],"answer":1,"solution":"TIG (Tungsten Inert Gas) uses non-consumable tungsten electrode."},{"id":1793,"text":"Which casting process uses a wax pattern?","options":[{"label":"A","text":"Sand casting"},{"label":"B","text":"Die casting"},{"label":"C","text":"Investment casting"},{"label":"D","text":"Centrifugal casting"}],"answer":2,"solution":"Investment (lost wax) casting: wax pattern coated with ceramic, melted out, metal poured."},{"id":1794,"text":"Kirchhoff's current law is based on:","options":[{"label":"A","text":"Conservation of energy"},{"label":"B","text":"Conservation of charge"},{"label":"C","text":"Ohm's law"},{"label":"D","text":"Faraday's law"}],"answer":1,"solution":"KCL: sum of currents entering = sum leaving (charge conservation)."},{"id":1795,"text":"The factor of safety is defined as:","options":[{"label":"A","text":"Ultimate load/Working load"},{"label":"B","text":"Ultimate strength/Working stress"},{"label":"C","text":"Yield stress/Working stress"},{"label":"D","text":"Both A and B"}],"answer":1,"solution":"FoS = ultimate load / allowable load = ultimate stress / working stress."},{"id":1796,"text":"The operation of enlarging a hole is called:","options":[{"label":"A","text":"Drilling"},{"label":"B","text":"Reaming"},{"label":"C","text":"Boring"},{"label":"D","text":"Counter-sinking"}],"answer":2,"solution":"Boring enlarges an existing hole. Reaming gives smooth finish."},{"id":1797,"text":"Which of the following is a linear data structure?","options":[{"label":"A","text":"Tree"},{"label":"B","text":"Queue"},{"label":"C","text":"Graph"},{"label":"D","text":"Binary Tree"}],"answer":1,"solution":"Queue is linear (elements in sequence). Tree and Graph aren on-linear data structures."},{"id":1798,"text":"Which scheduling algorithm is non-preemptive?","options":[{"label":"A","text":"Round Robin"},{"label":"B","text":"FCFS"},{"label":"C","text":"Shortest Remaining Time First"},{"label":"D","text":"Priority (Preemptive)"}],"answer":1,"solution":"First Come First Serve (FCFS) is non-preemptive — once a process gets the CPU, it runs until completion or I/O."},{"id":1799,"text":"The main function of an operating system is:","options":[{"label":"A","text":"Compiling programs"},{"label":"B","text":"Providing internet access"},{"label":"C","text":"Managing hardware resources"},{"label":"D","text":"Running applications"}],"answer":2,"solution":"The Osman ages CPU, memory, I/Ode vices, and provides resource allocation and protection."},{"id":1800,"text":"A steel rod of 10 mm diameter carries 31.4 kN load. Stress is:","options":[{"label":"A","text":"100 MPa"},{"label":"B","text":"200 MPa"},{"label":"C","text":"400 MPa"},{"label":"D","text":"314 MPa"}],"answer":2,"solution":"A = π(0.01)²/4 = 7.85×10⁻⁵ m². σ = 31400/7.85e-5 = 400 MPa."},{"id":1801,"text":"The number of bits in a nibble is:","options":[{"label":"A","text":"2"},{"label":"B","text":"4"},{"label":"C","text":"8"},{"label":"D","text":"16"}],"answer":1,"solution":"1 nibble = 4 bits. 1 byte = 2 nibbles = 8 bits."},{"id":1802,"text":"Class A amplifier has conduction angle of:","options":[{"label":"A","text":"90 degrees"},{"label":"B","text":"180 degrees"},{"label":"C","text":"360 degrees"},{"label":"D","text":"270 degrees"}],"answer":2,"solution":"Class A: conducts for full 360 degrees  of input cycle -> low efficiency (~25%)."},{"id":1803,"text":"The number of bits in a nibble is:","options":[{"label":"A","text":"2"},{"label":"B","text":"4"},{"label":"C","text":"8"},{"label":"D","text":"16"}],"answer":1,"solution":"1 nibble = 4 bits. 1 byte = 2 nibbles = 8 bits."},{"id":1804,"text":"A stack is implemented using an array. If the top pointer is at index 5, what is the current size of the stack?","options":[{"label":"A","text":"6"},{"label":"B","text":"5"},{"label":"C","text":"4"},{"label":"D","text":"7"}],"answer":0,"solution":"If top = 5 (0-indexed), there are 6 elements at indices 0 through 5."},{"id":1805,"text":"A diode in forward bias has:","options":[{"label":"A","text":"High resistance"},{"label":"B","text":"Low resistance"},{"label":"C","text":"Infinite resistance"},{"label":"D","text":"Zero current"}],"answer":1,"solution":"Forward bias: diode conducts with low resistance (~0.7 V drop for Si)."},{"id":1807,"text":"The Chezy'sco efficient C in Manning's formula relates to:","options":[{"label":"A","text":"Channel roughness"},{"label":"B","text":"Channel depth"},{"label":"C","text":"Both roughness and hydraulic radius"},{"label":"D","text":"Discharge"}],"answer":2,"solution":"Manning: V = (1/n)R^(2/3)S^(1/2). Chezy: C = (1/n)R^(1/6)."},{"id":1809,"text":"In am in-heap, the smallest element is at:","options":[{"label":"A","text":"Root"},{"label":"B","text":"Leftmost leaf"},{"label":"C","text":"Rightmost leaf"},{"label":"D","text":"Last node"}],"answer":0,"solution":"Min-heap property: parent  children, so root is always the minimum element."},{"id":1810,"text":"A 4-bit R-2R DAC uses resistors of values:","options":[{"label":"A","text":"Only R"},{"label":"B","text":"Only 2R"},{"label":"C","text":"Rand 2R"},{"label":"D","text":"R, 2R, 4R"}],"answer":2,"solution":"R-2R ladder DAC uses only Rand 2R resistors for binary-weighted conversion."},{"id":1811,"text":"A transistor has three terminals: base, collector, and:","options":[{"label":"A","text":"Gate"},{"label":"B","text":"Drain"},{"label":"C","text":"Emitter"},{"label":"D","text":"Source"}],"answer":2,"solution":"BJT terminals: Base, Collector, Emitter. FET: Gate, Drain, Source."},{"id":1812,"text":"Quick sand condition occurs when:","options":[{"label":"A","text":"Permeability is zero"},{"label":"B","text":"Upward seepage force equals submerged weight"},{"label":"C","text":"Soil is fully dry"},{"label":"D","text":"Water table is low"}],"answer":1,"solution":"Quicksand: upward hydraulic gradient  critical gradient (ic = Gs-1)/(1+e)."},{"id":1815,"text":"Kirchhoff's current law is based on:","options":[{"label":"A","text":"Conservation of energy"},{"label":"B","text":"Conservation of charge"},{"label":"C","text":"Ohm's law"},{"label":"D","text":"Faraday's law"}],"answer":1,"solution":"KCL: sum of currents entering = sum leaving (charge conservation)."},{"id":1816,"text":"The SI unit of thermal conductivity is:","options":[{"label":"A","text":"W/m"},{"label":"B","text":"W/mK"},{"label":"C","text":"J/kgK"},{"label":"D","text":"N/m^2"}],"answer":1,"solution":"Thermal conductivity k: W/(m.K)."},{"id":1818,"text":"Which data structure is used for implementing recursion?","options":[{"label":"A","text":"Queue"},{"label":"B","text":"Array"},{"label":"C","text":"Stack"},{"label":"D","text":"Linked List"}],"answer":2,"solution":"Recursion uses the call stack (LIFO) to store function call frames and return addresses."},{"id":1819,"text":"The output of XOR gate with inputs (1,1) is:","options":[{"label":"A","text":"1"},{"label":"B","text":"0"},{"label":"C","text":"High impedance"},{"label":"D","text":"Don't care"}],"answer":1,"solution":"XOR: output 1 when inputs differ, 0 when same. 11 = 0."},{"id":1820,"text":"What is the time complexity of binary search on a sorted array of n elements?","options":[{"label":"A","text":"O(n)"},{"label":"B","text":"O(log n)"},{"label":"C","text":"O(n^2)"},{"label":"D","text":"O(n log n)"}],"answer":1,"solution":"Binary search divides the search space in half each iteration, giving O(log n) time complexity."},{"id":1821,"text":"A transistor has three terminals: base, collector, and:","options":[{"label":"A","text":"Gate"},{"label":"B","text":"Drain"},{"label":"C","text":"Emitter"},{"label":"D","text":"Source"}],"answer":2,"solution":"BJT terminals: Base, Collector, Emitter. FET: Gate, Drain, Source."},{"id":1825,"text":"Which process is used to make threads on a bolt?","options":[{"label":"A","text":"Milling"},{"label":"B","text":"Drilling"},{"label":"C","text":"Threading"},{"label":"D","text":"Grinding"}],"answer":2,"solution":"Threading (using dies) cuts external threads on bolts and rods."},{"id":1826,"text":"Which scheduling algorithm is non-preemptive?","options":[{"label":"A","text":"Round Robin"},{"label":"B","text":"FCFS"},{"label":"C","text":"Shortest Remaining Time First"},{"label":"D","text":"Priority (Preemptive)"}],"answer":1,"solution":"First Come First Serve (FCFS) is non-preemptive - once a process gets the CPU, it runs until completion or I/O."},{"id":1828,"text":"The main function of an operating system is:","options":[{"label":"A","text":"Compiling programs"},{"label":"B","text":"Providing internet access"},{"label":"C","text":"Managing hardware resources"},{"label":"D","text":"Running applications"}],"answer":2,"solution":"The Osman ages CPU, memory, I/Ode vices, and provides resource allocation and protection."},{"id":1829,"text":"A 4-bit R-2R DAC uses resistors of values:","options":[{"label":"A","text":"Only R"},{"label":"B","text":"Only 2R"},{"label":"C","text":"Rand 2R"},{"label":"D","text":"R, 2R, 4R"}],"answer":2,"solution":"R-2R ladder DAC uses only Rand 2R resistors for binary-weighted conversion."},{"id":1830,"text":"Which of the following is a universal gate?","options":[{"label":"A","text":"AND"},{"label":"B","text":"OR"},{"label":"C","text":"NOT"},{"label":"D","text":"NAND"}],"answer":3,"solution":"NAND and NOR are universal gates - any Boolean function can be implemented using only NAND (or only NOR) gates."},{"id":1831,"text":"In am in-heap, the smallest element is at:","options":[{"label":"A","text":"Root"},{"label":"B","text":"Leftmost leaf"},{"label":"C","text":"Rightmost leaf"},{"label":"D","text":"Last node"}],"answer":0,"solution":"Min-heap property: parent  children, so root is always the minimum element."},{"id":1832,"text":"An ideal op-amp has infinite:","options":[{"label":"A","text":"Output impedance"},{"label":"B","text":"Input impedance"},{"label":"C","text":"Bandwidth"},{"label":"D","text":"Both Band C"}],"answer":1,"solution":"Ideal op-amp: infinite input impedance, zero output impedance, infinite gain."},{"id":1833,"text":"A heat engine rejects 300 J to sink while doing 200 J work. Heat supplied is:","options":[{"label":"A","text":"100 J"},{"label":"B","text":"300 J"},{"label":"C","text":"500 J"},{"label":"D","text":"600 J"}],"answer":2,"solution":"Q = W + Q = 200 + 300 = 500 J."},{"id":1834,"text":"In a CPU, what is the main function of the cache memory?","options":[{"label":"A","text":"To increase the size of the main memory"},{"label":"B","text":"To decrease the time taken to access the main memory"},{"label":"C","text":"To increase the speed of the CPU"},{"label":"D","text":"To decrease the power consumption of the CPU"}],"answer":1,"solution":"The main function of the cache memory in a CPU is to store frequently used data and instructions, which reduces the time taken to access the main memory."},{"id":1835,"text":"The impedance of a capacitor of capacitance C at frequency  is:","options":[{"label":"A","text":"jC"},{"label":"B","text":"1/(jC)"},{"label":"C","text":"C"},{"label":"D","text":"1/(C)"}],"answer":1,"solution":"Zc = 1/(jC) = -j/(C)."},{"id":1838,"text":"A steel rod of 10 mm diameter carries 31.4 kN load. Stress is:","options":[{"label":"A","text":"100 MPa"},{"label":"B","text":"200 MPa"},{"label":"C","text":"400 MPa"},{"label":"D","text":"314 MPa"}],"answer":2,"solution":"A = pi(0.01)^2/4 = 7.85x10 m^2.  = 31400/7.85e-5 = 400 MPa."},{"id":1839,"text":"Beam deflection is maximum at:","options":[{"label":"A","text":"Supports"},{"label":"B","text":"Point of load"},{"label":"C","text":"Depends on loading"},{"label":"D","text":"Center always"}],"answer":2,"solution":"Deflection depends on loading type. For UDL: max at center. For point load: at load point."},{"id":1841,"text":"The bending moment at a simply supported beam's center with point load P at center is:","options":[{"label":"A","text":"PL/2"},{"label":"B","text":"PL/4"},{"label":"C","text":"PL/8"},{"label":"D","text":"PL"}],"answer":1,"solution":"Mmax = PL/4 for simply supported beam with central point load."},{"id":1842,"text":"The total hardness of water is due to:","options":[{"label":"A","text":"Na and K"},{"label":"B","text":"Ca^2 and Mg^2"},{"label":"C","text":"Cl and SO^2"},{"label":"D","text":"Fe^2 and Mn^2"}],"answer":1,"solution":"Hardness: Ca^2 and Mg^2 ions (temporary: bicarbonates, permanent: sulfates/chlorides)."},{"id":1844,"text":"In am in-heap, the smallest element is at:","options":[{"label":"A","text":"Root"},{"label":"B","text":"Leftmost leaf"},{"label":"C","text":"Rightmost leaf"},{"label":"D","text":"Last node"}],"answer":0,"solution":"Min-heap property: parent  children, so root is always the minimum element."},{"id":1847,"text":"The pH of pure water is:","options":[{"label":"A","text":"0"},{"label":"B","text":"14"},{"label":"C","text":"7"},{"label":"D","text":"10"}],"answer":2,"solution":"Pure water has pH 7 at 25 degrees C (neutral)."},{"id":1848,"text":"A Zener diode is used for:","options":[{"label":"A","text":"Rectification"},{"label":"B","text":"Amplification"},{"label":"C","text":"Voltage regulation"},{"label":"D","text":"Switching"}],"answer":2,"solution":"Zener diode maintains constant voltage in reverse breakdown -> voltage regulator."},{"id":1849,"text":"Which flip-flop has no race condition?","options":[{"label":"A","text":"SR"},{"label":"B","text":"JK"},{"label":"C","text":"Master-slave JK"},{"label":"D","text":"D"}],"answer":2,"solution":"Master-slave JK flip-flop eliminates race-around condition."},{"id":1852,"text":"The number of bits in a nibble is:","options":[{"label":"A","text":"2"},{"label":"B","text":"4"},{"label":"C","text":"8"},{"label":"D","text":"16"}],"answer":1,"solution":"1 nibble = 4 bits. 1 byte = 2 nibbles = 8 bits."},{"id":1853,"text":"Which of the following is a linear data structure?","options":[{"label":"A","text":"Tree"},{"label":"B","text":"Queue"},{"label":"C","text":"Graph"},{"label":"D","text":"Binary Tree"}],"answer":1,"solution":"Queue is linear (elements in sequence). Tree and Graph aren on-linear data structures."},{"id":1855,"text":"Quick sand condition occurs when:","options":[{"label":"A","text":"Permeability is zero"},{"label":"B","text":"Upward seepage force equals submerged weight"},{"label":"C","text":"Soil is fully dry"},{"label":"D","text":"Water table is low"}],"answer":1,"solution":"Quicksand: upward hydraulic gradient  critical gradient (ic = Gs-1)/(1+e)."},{"id":1858,"text":"The RMS value of sinusoidal voltage v = 10 sin(t) is:","options":[{"label":"A","text":"10 V"},{"label":"B","text":"7.07 V"},{"label":"C","text":"5 V"},{"label":"D","text":"14.14 V"}],"answer":1,"solution":"Vrms = Vm/sqrt2 = 10/1.414 = 7.07 V."},{"id":1859,"text":"The SI unit of thermal conductivity is:","options":[{"label":"A","text":"W/m"},{"label":"B","text":"W/mK"},{"label":"C","text":"J/kgK"},{"label":"D","text":"N/m^2"}],"answer":1,"solution":"Thermal conductivity k: W/(m.K)."},{"id":1860,"text":"The operation of enlarging a hole is called:","options":[{"label":"A","text":"Drilling"},{"label":"B","text":"Reaming"},{"label":"C","text":"Boring"},{"label":"D","text":"Counter-sinking"}],"answer":2,"solution":"Boring enlarges an existing hole. Reaming gives smooth finish."},{"id":1862,"text":"The number of input lines for 3-to-8 decoder is:","options":[{"label":"A","text":"8"},{"label":"B","text":"2"},{"label":"C","text":"3"},{"label":"D","text":"4"}],"answer":2,"solution":"3-to-8 decoder: 3 inputs, 8 outputs."},{"id":1863,"text":"What is the time complexity of binary search on a sorted array of n elements?","options":[{"label":"A","text":"O(n)"},{"label":"B","text":"O(log n)"},{"label":"C","text":"O(n^2)"},{"label":"D","text":"O(n log n)"}],"answer":1,"solution":"Binary search divides the search space in half each iteration, giving O(log n) time complexity."},{"id":1864,"text":"In an isothermal process, which quantity remains constant?","options":[{"label":"A","text":"Pressure"},{"label":"B","text":"Volume"},{"label":"C","text":"Temperature"},{"label":"D","text":"Entropy"}],"answer":2,"solution":"Isothermal: T = constant, PV = constant (for ideal gas)."},{"id":1866,"text":"The bearing capacity of soil is improved by:","options":[{"label":"A","text":"Water addition"},{"label":"B","text":"Compaction"},{"label":"C","text":"Excavation"},{"label":"D","text":"Aeration"}],"answer":1,"solution":"Compaction increases soil density -> higher bearing capacity."},{"id":1867,"text":"The standard penetration test (SPT) N-value indicates:","options":[{"label":"A","text":"Water content"},{"label":"B","text":"Soil density/strength"},{"label":"C","text":"Permeability"},{"label":"D","text":"Plasticity"}],"answer":1,"solution":"SPT N-value correlates with relative density and strength of soil."},{"id":1868,"text":"In a control system, what is the purpose of the feedback loop?","options":[{"label":"A","text":"To increase the gain of the system"},{"label":"B","text":"To decrease the stability of the system"},{"label":"C","text":"To reduce the error between the desired output and the actual output"},{"label":"D","text":"To increase the noise in the system"}],"answer":2,"solution":"The purpose of the feedback loop in a control system is to reduce the error between the desired output and the actual output by continuously monitoring the output and adjusting the input to minimize the error."},{"id":1870,"text":"TIG welding uses which electrode?","options":[{"label":"A","text":"Consumable"},{"label":"B","text":"Non-consumable tungsten"},{"label":"C","text":"Copper"},{"label":"D","text":"Steel"}],"answer":1,"solution":"TIG (Tungsten Inert Gas) uses non-consumable tungsten electrode."},{"id":1871,"text":"What does the following C expression evaluate to? (Assume i = 5) i++ + ++i","options":[{"label":"A","text":"10"},{"label":"B","text":"11"},{"label":"C","text":"12"},{"label":"D","text":"Undefined"}],"answer":2,"solution":"i++ uses current value (5) then increments to 6. ++i increments to 7 then uses 7. So 5 + 7 = 12."},{"id":1872,"text":"An ideal op-amp has infinite:","options":[{"label":"A","text":"Output impedance"},{"label":"B","text":"Input impedance"},{"label":"C","text":"Bandwidth"},{"label":"D","text":"Both Band C"}],"answer":1,"solution":"Ideal op-amp: infinite input impedance, zero output impedance, infinite gain."},{"id":1874,"text":"In orthogonal cutting, the cutting edge is:","options":[{"label":"A","text":"Parallel to work surface"},{"label":"B","text":"Perpendicular to cutting velocity"},{"label":"C","text":"At 45 degrees"},{"label":"D","text":"Inclined"}],"answer":1,"solution":"Orthogonal cutting: cutting edge  to cutting velocity direction."},{"id":1875,"text":"Thevenin's theorem is used to simplify:","options":[{"label":"A","text":"Non-linear circuits"},{"label":"B","text":"Linear circuits"},{"label":"C","text":"Digital circuits"},{"label":"D","text":"Magnetic circuits"}],"answer":1,"solution":"Thevenin's theorem applies to linear circuits (voltage source + series resistance)."},{"id":1876,"text":"The worst-case time complexity of quicksort is:","options":[{"label":"A","text":"O(log n)"},{"label":"B","text":"O(n log n)"},{"label":"C","text":"O(n^2)"},{"label":"D","text":"O(n)"}],"answer":2,"solution":"Quicksort worst-case O(n^2) when pivot is smallest/largest element (e.g., sorted array with naive pivot)."},{"id":1878,"text":"Which language is accepted by Pushdown Automata?","options":[{"label":"A","text":"Regular"},{"label":"B","text":"Context-Free"},{"label":"C","text":"Context-Sensitive"},{"label":"D","text":"Recursively Enumerable"}],"answer":1,"solution":"PDA accepts exactly the class of Context-Free Languages (CFL)."},{"id":1879,"text":"The height of a complete binary tree with nno des is:","options":[{"label":"A","text":"n"},{"label":"B","text":"n/2"},{"label":"C","text":"logn"},{"label":"D","text":"sqrtn"}],"answer":2,"solution":"Height of a complete binary tree with nno des is logn."},{"id":1881,"text":"A heat engine rejects 300 J to sink while doing 200 J work. Heat supplied is:","options":[{"label":"A","text":"100 J"},{"label":"B","text":"300 J"},{"label":"C","text":"500 J"},{"label":"D","text":"600 J"}],"answer":2,"solution":"Q = W + Q = 200 + 300 = 500 J."},{"id":1882,"text":"How many AND gates are needed for 8-to-1 multiplexer?","options":[{"label":"A","text":"4"},{"label":"B","text":"6"},{"label":"C","text":"8"},{"label":"D","text":"16"}],"answer":2,"solution":"8-to-1 MUX needs 8 AND gates (one per input) + 1 OR gate."},{"id":1883,"text":"In a computer network, what is the purpose of the router?","options":[{"label":"A","text":"To connect multiple devices within a network"},{"label":"B","text":"To connect multiple networks together"},{"label":"C","text":"To provide network security"},{"label":"D","text":"To provide network storage"}],"answer":1,"solution":"The purpose of the router in a computer network is to connect multiple networks together and route traffic between them."},{"id":1884,"text":"A 4-bit R-2R DAC uses resistors of values:","options":[{"label":"A","text":"Only R"},{"label":"B","text":"Only 2R"},{"label":"C","text":"Rand 2R"},{"label":"D","text":"R, 2R, 4R"}],"answer":2,"solution":"R-2R ladder DAC uses only Rand 2R resistors for binary-weighted conversion."},{"id":1885,"text":"Which of the following is NOT a valid Boolean algebra property?","options":[{"label":"A","text":"A . 0 = 0"},{"label":"B","text":"A + 1 = 1"},{"label":"C","text":"A . A = A"},{"label":"D","text":"A + A = 0"}],"answer":3,"solution":"A + A = A (idempotent law), not 0. A + A = 1 and A . A = 0."},{"id":1890,"text":"Concrete is strong in:","options":[{"label":"A","text":"Tension"},{"label":"B","text":"Compression"},{"label":"C","text":"Shear"},{"label":"D","text":"Torsion"}],"answer":1,"solution":"Concrete has high compressive strength but low tensile strength (reinforced with steel)."},{"id":1891,"text":"The Chezy'sco efficient C in Manning's formula relates to:","options":[{"label":"A","text":"Channel roughness"},{"label":"B","text":"Channel depth"},{"label":"C","text":"Both roughness and hydraulic radius"},{"label":"D","text":"Discharge"}],"answer":2,"solution":"Manning: V = (1/n)R^(2/3)S^(1/2). Chezy: C = (1/n)R^(1/6)."},{"id":1892,"text":"Which scheduling algorithm is non-preemptive?","options":[{"label":"A","text":"Round Robin"},{"label":"B","text":"FCFS"},{"label":"C","text":"Shortest Remaining Time First"},{"label":"D","text":"Priority (Preemptive)"}],"answer":1,"solution":"First Come First Serve (FCFS) is non-preemptive - once a process gets the CPU, it runs until completion or I/O."},{"id":1894,"text":"Binary equivalent of decimal 15 is:","options":[{"label":"A","text":"1010"},{"label":"B","text":"1100"},{"label":"C","text":"1111"},{"label":"D","text":"1001"}],"answer":2,"solution":"15 = 8+4+2+1 = 1111."},{"id":1896,"text":"Class A amplifier has conduction angle of:","options":[{"label":"A","text":"90 degrees"},{"label":"B","text":"180 degrees"},{"label":"C","text":"360 degrees"},{"label":"D","text":"270 degrees"}],"answer":2,"solution":"Class A: conducts for full 360 degrees  of input cycle -> low efficiency (~25%)."},{"id":1897,"text":"In virtual memory, which technique is used for address translation?","options":[{"label":"A","text":"Segmentation"},{"label":"B","text":"Compaction"},{"label":"C","text":"Paging"},{"label":"D","text":"Swapping"}],"answer":2,"solution":"Paging maps virtual addresses to physical addresses using page tables, enabling virtual memory."},{"id":1898,"text":"Two 10  resistors in parallel give equivalent resistance:","options":[{"label":"A","text":"20"},{"label":"B","text":"5"},{"label":"C","text":"10"},{"label":"D","text":"2.5"}],"answer":1,"solution":"1/Rp = 1/10 + 1/10 = 2/10 -> Rp = 5 ."},{"id":1899,"text":"Which of the following is a volatile memory?","options":[{"label":"A","text":"ROM"},{"label":"B","text":"Hard disk"},{"label":"C","text":"RAM"},{"label":"D","text":"Flash drive"}],"answer":2,"solution":"RAM (Random Access Memory) is volatile - data is lost when power is turned off."},{"id":1901,"text":"A steel rod of 10 mm diameter carries 31.4 kN load. Stress is:","options":[{"label":"A","text":"100 MPa"},{"label":"B","text":"200 MPa"},{"label":"C","text":"400 MPa"},{"label":"D","text":"314 MPa"}],"answer":2,"solution":"A = pi(0.01)^2/4 = 7.85x10 m^2.  = 31400/7.85e-5 = 400 MPa."},{"id":1902,"text":"The modulus of rigidity relates shear stress to:","options":[{"label":"A","text":"Normal strain"},{"label":"B","text":"Shear strain"},{"label":"C","text":"Volumetric strain"},{"label":"D","text":"Lateral strain"}],"answer":1,"solution":"G = / (shear stress / shear strain)."},{"id":1903,"text":"A simply supported beam with UDL has maximum bending moment at:","options":[{"label":"A","text":"Ends"},{"label":"B","text":"Mid-span"},{"label":"C","text":"Quarter span"},{"label":"D","text":"Supports"}],"answer":1,"solution":"Mmax = wL^2/8 at mid-span for simply supported beam with UDL."},{"id":1905,"text":"A language accepted by a Finite Automaton is called:","options":[{"label":"A","text":"Regular language"},{"label":"B","text":"Context-free language"},{"label":"C","text":"Context-sensitive language"},{"label":"D","text":"Recursively enumerable language"}],"answer":0,"solution":"Finite automata accept exactly the class of regular languages (Type 3 in Chomsky hierarchy)."},{"id":1906,"text":"The unit of entropy is:","options":[{"label":"A","text":"J/K"},{"label":"B","text":"kJ/K"},{"label":"C","text":"kJ/kgK"},{"label":"D","text":"All of these"}],"answer":1,"solution":"Entropy units: J/K (total) or kJ/kg.K (specific)."},{"id":1908,"text":"The Euler's buckling load for a column depends on:","options":[{"label":"A","text":"Material only"},{"label":"B","text":"Length only"},{"label":"C","text":"Length, E, I, and end conditions"},{"label":"D","text":"Cross-section only"}],"answer":2,"solution":"Pcr = pi^2EI/(Le)^2. Depends on E, I, effective length (end conditions)."},{"id":1909,"text":"A counter with 4 flip-flops can count up to:","options":[{"label":"A","text":"8"},{"label":"B","text":"16"},{"label":"C","text":"4"},{"label":"D","text":"32"}],"answer":1,"solution":"4-bit counter: 2 = 16 states (0 to 15)."},{"id":1910,"text":"Which traversal gives sorted order in a BST?","options":[{"label":"A","text":"Preorder"},{"label":"B","text":"Postorder"},{"label":"C","text":"Inorder"},{"label":"D","text":"Level order"}],"answer":2,"solution":"Inorder traversal of BST visits nodes in ascending order (left -> root -> right)."},{"id":1912,"text":"In a microprocessor, what is the function of the Arithmetic Logic Unit (ALU)?","options":[{"label":"A","text":"To control the flow of data between registers"},{"label":"B","text":"To perform arithmetic and logical operations"},{"label":"C","text":"To store data temporarily"},{"label":"D","text":"To provide the clock signal"}],"answer":1,"solution":"The Arithmetic Logic Unit (ALU) in a microprocessor performs arithmetic operations such as addition, subtraction, multiplication, and division, as well as logical operations such as AND, OR, and NOT."},{"id":1913,"text":"The plasticity chart classifies soil based on:","options":[{"label":"A","text":"Grain size"},{"label":"B","text":"Liquid limit and plasticity index"},{"label":"C","text":"Permeability"},{"label":"D","text":"Compaction"}],"answer":1,"solution":"Casagrande's plasticity chart: LL vs PI to classify fine-grained soils (CL, CH, ML, MH)."},{"id":1915,"text":"A material that undergoes large deformation before fracture is called:","options":[{"label":"A","text":"Brittle"},{"label":"B","text":"Ductile"},{"label":"C","text":"Elastic"},{"label":"D","text":"Plastic"}],"answer":1,"solution":"Ductile materials (steel, aluminum) undergo significant plastic deformation before fracture."},{"id":1917,"text":"The cutting speed in a lathe is measured in:","options":[{"label":"A","text":"RPM"},{"label":"B","text":"m/min"},{"label":"C","text":"mm/rev"},{"label":"D","text":"mm"}],"answer":1,"solution":"Cutting speed = piDN/1000 m/min (D in mm, N in RPM)."},{"id":1918,"text":"The gain of an on-inverting amplifier with Rf=10 k and R1=1 k is:","options":[{"label":"A","text":"10"},{"label":"B","text":"11"},{"label":"C","text":"9"},{"label":"D","text":"1"}],"answer":1,"solution":"Gain = 1 + Rf/R1 = 1 + 10 = 11."},{"id":1919,"text":"A stack is implemented using an array. If the top pointer is at index 5, what is the current size of the stack?","options":[{"label":"A","text":"6"},{"label":"B","text":"5"},{"label":"C","text":"4"},{"label":"D","text":"7"}],"answer":0,"solution":"If top = 5 (0-indexed), there are 6 elements at indices 0 through 5."},{"id":1920,"text":"The effective span of a simply supported beam is:","options":[{"label":"A","text":"Clear span"},{"label":"B","text":"Center to center of supports"},{"label":"C","text":"Clear span + effective depth"},{"label":"D","text":"Overall length"}],"answer":2,"solution":"For simply supported: Le = min(Lc + d, c/c distance of supports)."},{"id":1921,"text":"Kirchhoff's current law is based on:","options":[{"label":"A","text":"Conservation of energy"},{"label":"B","text":"Conservation of charge"},{"label":"C","text":"Ohm's law"},{"label":"D","text":"Faraday's law"}],"answer":1,"solution":"KCL: sum of currents entering = sum leaving (charge conservation)."},{"id":1922,"text":"In am in-heap, the smallest element is at:","options":[{"label":"A","text":"Root"},{"label":"B","text":"Leftmost leaf"},{"label":"C","text":"Rightmost leaf"},{"label":"D","text":"Last node"}],"answer":0,"solution":"Min-heap property: parent  children, so root is always the minimum element."},{"id":1923,"text":"The COP of a refrigerator is 4. If it extracts 200 J from cold reservoir, work input is:","options":[{"label":"A","text":"20 J"},{"label":"B","text":"40 J"},{"label":"C","text":"50 J"},{"label":"D","text":"200 J"}],"answer":2,"solution":"COP = Q/W -> 4 = 200/W -> W = 50 J."},{"id":1924,"text":"The first law of thermodynamics is essentially:","options":[{"label":"A","text":"Conservation of mass"},{"label":"B","text":"Conservation of energy"},{"label":"C","text":"Conservation of momentum"},{"label":"D","text":"Law of entropy"}],"answer":1,"solution":"U = Q - W (energy conservation for thermodynamic systems)."},{"id":1925,"text":"The Manning's roughness coefficient n for concrete is about:","options":[{"label":"A","text":"0.001"},{"label":"B","text":"0.035"},{"label":"C","text":"0.013"},{"label":"D","text":"0.1"}],"answer":2,"solution":"Manning's n for concrete: 0.012-0.015 (typically 0.013)."},{"id":1929,"text":"In a CPU, what is the main function of the cache memory?","options":[{"label":"A","text":"To increase the size of the main memory"},{"label":"B","text":"To decrease the time taken to access the main memory"},{"label":"C","text":"To increase the speed of the CPU"},{"label":"D","text":"To decrease the power consumption of the CPU"}],"answer":1,"solution":"The main function of the cache memory in a CPU is to store frequently used data and instructions, which reduces the time taken to access the main memory."},{"id":1931,"text":"The bending moment at a simply supported beam's center with point load P at center is:","options":[{"label":"A","text":"PL/2"},{"label":"B","text":"PL/4"},{"label":"C","text":"PL/8"},{"label":"D","text":"PL"}],"answer":1,"solution":"Mmax = PL/4 for simply supported beam with central point load."},{"id":1932,"text":"The main function of an operating system is:","options":[{"label":"A","text":"Compiling programs"},{"label":"B","text":"Providing internet access"},{"label":"C","text":"Managing hardware resources"},{"label":"D","text":"Running applications"}],"answer":2,"solution":"The Osman ages CPU, memory, I/Ode vices, and provides resource allocation and protection."},{"id":1935,"text":"The output of XOR gate with inputs (1,1) is:","options":[{"label":"A","text":"1"},{"label":"B","text":"0"},{"label":"C","text":"High impedance"},{"label":"D","text":"Don't care"}],"answer":1,"solution":"XOR: output 1 when inputs differ, 0 when same. 11 = 0."},{"id":1936,"text":"The unit of moment of inertia is:","options":[{"label":"A","text":"N/m"},{"label":"B","text":"kg/m^2"},{"label":"C","text":"m"},{"label":"D","text":"N.m"}],"answer":2,"solution":"Moment of inertia (area) has units of m."}]},{"name":"General Aptitude","count":59,"questions":[{"id":1653,"text":"The number of diagonals in a pentagon is:","options":[{"label":"A","text":"3"},{"label":"B","text":"4"},{"label":"C","text":"5"},{"label":"D","text":"6"}],"answer":2,"solution":"n(n-3)/2 = 5(2)/2 = 5 diagonals."},{"id":1654,"text":"Select the synonym of \"Ephemeral\":","options":[{"label":"A","text":"Permanent"},{"label":"B","text":"Long-lasting"},{"label":"C","text":"Transient"},{"label":"D","text":"Eternal"}],"answer":2,"solution":"Ephemeral = short-lived/transient. Opposite = permanent."},{"id":1656,"text":"A die is rolled once. Probability of getting an even number is:","options":[{"label":"A","text":"1/6"},{"label":"B","text":"1/2"},{"label":"C","text":"2/3"},{"label":"D","text":"1/3"}],"answer":1,"solution":"Even: 2,4,6 (3 outcomes). P = 3/6 = 1/2."},{"id":1657,"text":"If x + y = 10 and xy = 21, then x² + y² is:","options":[{"label":"A","text":"100"},{"label":"B","text":"79"},{"label":"C","text":"58"},{"label":"D","text":"42"}],"answer":2,"solution":"x²+y² = (x+y)² - 2xy = 100 - 42 = 58."},{"id":1677,"text":"The perimeter of a square is 40 cm. Its area is:","options":[{"label":"A","text":"80 cm²"},{"label":"B","text":"160 cm²"},{"label":"C","text":"100 cm²"},{"label":"D","text":"200 cm²"}],"answer":2,"solution":"Side = 40/4 = 10 cm. Area = 10² = 100 cm²."},{"id":1682,"text":"The sum of ages of A and B is 45 years. 5 years from now, the ratio of their ages will be 4:5. Find the current age of A.","options":[{"label":"A","text":"15 years"},{"label":"B","text":"20 years"},{"label":"C","text":"25 years"},{"label":"D","text":"30 years"}],"answer":0,"solution":"Let A's age = x, B's age = 45-x. After 5 years: (x+5)/(50-x) = 4/5. 5x+25 = 200-4x. 9x = 175. x = 15."},{"id":1683,"text":"If LOGIC is coded as 15-15-7-9-3, then what is the code for MATH?","options":[{"label":"A","text":"1-13-20-8"},{"label":"B","text":"13-1-20-8"},{"label":"C","text":"14-1-21-9"},{"label":"D","text":"12-1-19-7"}],"answer":2,"solution":"Each letter is coded as its position + 1. L(12)+3=15, O(15)+0=15, G(7)+0=7, I(9)+0=9, C(3)+0=3. For MATH: M(13)+1=14, A(1)+0=1, T(20)+1=21, H(8)+1=9 ⇒ 14-1-21-9."},{"id":1694,"text":"A train 150 m long passes a pole in 15 seconds. Find the speed of the train in km/h.","options":[{"label":"A","text":"12 km/h"},{"label":"B","text":"24 km/h"},{"label":"C","text":"36 km/h"},{"label":"D","text":"48 km/h"}],"answer":2,"solution":"Speed = distance/time = 150/15 = 10 m/s. In km/h: 10 × (18/5) = 36 km/h."},{"id":1697,"text":"If 5 men can build a wall in 12 days, how many days will 10 men take?","options":[{"label":"A","text":"24"},{"label":"B","text":"12"},{"label":"C","text":"6"},{"label":"D","text":"3"}],"answer":2,"solution":"M1D1 = M2D2 ⇒ 5×12 = 10×D2 ⇒ D2 = 6 days."},{"id":1698,"text":"Find the missing number: 2, 6, 12, 20, ?","options":[{"label":"A","text":"28"},{"label":"B","text":"24"},{"label":"C","text":"30"},{"label":"D","text":"36"}],"answer":2,"solution":"Pattern: 1×2=2, 2×3=6, 3×4=12, 4×5=20, 5×6=30."},{"id":1709,"text":"Find the odd one out: 2, 4, 8, 16, 24, 32","options":[{"label":"A","text":"4"},{"label":"B","text":"8"},{"label":"C","text":"24"},{"label":"D","text":"32"}],"answer":2,"solution":"All others are powers of 2 (2¹, 2², 2³, 24, 25). 24 is not a power of 2."},{"id":1713,"text":"If a train running at 72 km/h crosses a pole in 10 s, the length of train is:","options":[{"label":"A","text":"100 m"},{"label":"B","text":"150 m"},{"label":"C","text":"200 m"},{"label":"D","text":"250 m"}],"answer":2,"solution":"Speed = 72×(5/18) = 20 m/s. Length = 20×10 = 200 m."},{"id":1714,"text":"Find the next term: 3, 9, 27, 81, ?","options":[{"label":"A","text":"162"},{"label":"B","text":"189"},{"label":"C","text":"243"},{"label":"D","text":"324"}],"answer":2,"solution":"Geometric progression with ratio 3: 35 = 243."},{"id":1715,"text":"A man buys a book for ₹500 and sells it for ₹600. Profit percentage is:","options":[{"label":"A","text":"10%"},{"label":"B","text":"20%"},{"label":"C","text":"15%"},{"label":"D","text":"25%"}],"answer":1,"solution":"Profit = 100, CP = 500. Profit% = 100/500 × 100 = 20%."},{"id":1716,"text":"Which word is opposite in meaning to \"Benevolent\"?","options":[{"label":"A","text":"Kind"},{"label":"B","text":"Generous"},{"label":"C","text":"Malevolent"},{"label":"D","text":"Charitable"}],"answer":2,"solution":"Benevolent = kind/generous. Opposite = malevolent (wicked/hostile)."},{"id":1717,"text":"If 3x + 2 = 11, then x = ?","options":[{"label":"A","text":"1"},{"label":"B","text":"3"},{"label":"C","text":"4"},{"label":"D","text":"2"}],"answer":1,"solution":"3x = 9 ⇒ x = 3."},{"id":1742,"text":"If 15 workers can build a wall in 8 days, how many workers are needed to build same wall in 6 days?","options":[{"label":"A","text":"12"},{"label":"B","text":"18"},{"label":"C","text":"20"},{"label":"D","text":"25"}],"answer":2,"solution":"M1D1 = M2D2 ⇒ 15×8 = M2×6 ⇒ M2 = 20."},{"id":1743,"text":"A car travels 60 km in 1.5 hours. Its average speed is:","options":[{"label":"A","text":"30 km/h"},{"label":"B","text":"40 km/h"},{"label":"C","text":"50 km/h"},{"label":"D","text":"90 km/h"}],"answer":1,"solution":"Speed = 60/1.5 = 40 km/h."},{"id":1744,"text":"Choose the correct spelling:","options":[{"label":"A","text":"Mischeivous"},{"label":"B","text":"Mischievious"},{"label":"C","text":"Mischievous"},{"label":"D","text":"Mischevous"}],"answer":2,"solution":"Correct spelling: Mischievous."},{"id":1746,"text":"If the radius of a circle is doubled, the area becomes:","options":[{"label":"A","text":"Double"},{"label":"B","text":"Four times"},{"label":"C","text":"Eight times"},{"label":"D","text":"Same"}],"answer":1,"solution":"A ∝ r². If r → 2r, A → 4A."},{"id":1767,"text":"The simple interest on ₹1000 at 5% per annum for 2 years is:","options":[{"label":"A","text":"₹50"},{"label":"B","text":"₹100"},{"label":"C","text":"₹200"},{"label":"D","text":"₹25"}],"answer":1,"solution":"SI = P×R×T/100 = 1000×5×2/100 = ₹100."},{"id":1780,"text":"If LOGIC is coded as 15-15-7-9-3, then what is the code for MATH?","options":[{"label":"A","text":"1-13-20-8"},{"label":"B","text":"13-1-20-8"},{"label":"C","text":"14-1-21-9"},{"label":"D","text":"12-1-19-7"}],"answer":2,"solution":"Each letter is coded as its position + 1. L(12)+3=15, O(15)+0=15, G(7)+0=7, I(9)+0=9, C(3)+0=3. For MATH: M(13)+1=14, A(1)+0=1, T(20)+1=21, H(8)+1=9 → 14-1-21-9."},{"id":1782,"text":"The sum of ages of A and B is 45 years. 5 years from now, the ratio of their ages will be 4:5. Find the current age of A.","options":[{"label":"A","text":"15 years"},{"label":"B","text":"20 years"},{"label":"C","text":"25 years"},{"label":"D","text":"30 years"}],"answer":0,"solution":"Let A's age = x, B's age = 45-x. After 5 years: (x+5)/(50-x) = 4/5. 5x+25 = 200-4x. 9x = 175. x = 15."},{"id":1783,"text":"The simple interest on ₹1000 at 5% per annum for 2 years is:","options":[{"label":"A","text":"₹50"},{"label":"B","text":"₹100"},{"label":"C","text":"₹200"},{"label":"D","text":"₹25"}],"answer":1,"solution":"SI = P×R×T/100 = 1000×5×2/100 = ₹100."},{"id":1787,"text":"Which word is opposite in meaning to \"Benevolent\"?","options":[{"label":"A","text":"Kind"},{"label":"B","text":"Generous"},{"label":"C","text":"Malevolent"},{"label":"D","text":"Charitable"}],"answer":2,"solution":"Benevolent = kind/generous. Opposite = malevolent (wicked/hostile)."},{"id":1792,"text":"If a train running at 72 km/h crosses a pole in 10 s, the length of train is:","options":[{"label":"A","text":"100 m"},{"label":"B","text":"150 m"},{"label":"C","text":"200 m"},{"label":"D","text":"250 m"}],"answer":2,"solution":"Speed = 72×(5/18) = 20 m/s. Length = 20×10 = 200 m."},{"id":1806,"text":"If 5 men can build a wall in 12 days, how many days will 10 men take?","options":[{"label":"A","text":"24"},{"label":"B","text":"12"},{"label":"C","text":"6"},{"label":"D","text":"3"}],"answer":2,"solution":"MD = MD -> 5x12 = 10xD -> D = 6 days."},{"id":1813,"text":"Find the next term: 3, 9, 27, 81, ?","options":[{"label":"A","text":"162"},{"label":"B","text":"189"},{"label":"C","text":"243"},{"label":"D","text":"324"}],"answer":2,"solution":"Geometric progression with ratio 3: 3 = 243."},{"id":1814,"text":"Find the odd one out: 2, 4, 8, 16, 24, 32","options":[{"label":"A","text":"4"},{"label":"B","text":"8"},{"label":"C","text":"24"},{"label":"D","text":"32"}],"answer":2,"solution":"All others are powers of 2 (2, 2^2, 2, 2, 2). 24 is not a power of 2."},{"id":1817,"text":"If 3x + 2 = 11, then x = ?","options":[{"label":"A","text":"1"},{"label":"B","text":"3"},{"label":"C","text":"4"},{"label":"D","text":"2"}],"answer":1,"solution":"3x = 9 -> x = 3."},{"id":1822,"text":"The perimeter of a square is 40 cm. Its area is:","options":[{"label":"A","text":"80 cm^2"},{"label":"B","text":"160 cm^2"},{"label":"C","text":"100 cm^2"},{"label":"D","text":"200 cm^2"}],"answer":2,"solution":"Side = 40/4 = 10 cm. Area = 10^2 = 100 cm^2."},{"id":1823,"text":"If x + y = 10 and xy = 21, then x^2 + y^2 is:","options":[{"label":"A","text":"100"},{"label":"B","text":"79"},{"label":"C","text":"58"},{"label":"D","text":"42"}],"answer":2,"solution":"x^2+y^2 = (x+y)^2 - 2xy = 100 - 42 = 58."},{"id":1824,"text":"Choose the correct spelling:","options":[{"label":"A","text":"Mischeivous"},{"label":"B","text":"Mischievious"},{"label":"C","text":"Mischievous"},{"label":"D","text":"Mischevous"}],"answer":2,"solution":"Correct spelling: Mischievous."},{"id":1827,"text":"A die is rolled once. Probability of getting an even number is:","options":[{"label":"A","text":"1/6"},{"label":"B","text":"1/2"},{"label":"C","text":"2/3"},{"label":"D","text":"1/3"}],"answer":1,"solution":"Even: 2,4,6 (3 outcomes). P = 3/6 = 1/2."},{"id":1836,"text":"A company has 15 employees, and each employee can speak two languages. What is the minimum number of languages that the company must have to satisfy this condition?","options":[{"label":"A","text":"7"},{"label":"B","text":"8"},{"label":"C","text":"15"},{"label":"D","text":"30"}],"answer":1,"solution":"Since each employee can speak two languages, we can consider each employee as an edge in a graph, and each language as a node. The minimum number of languages required is equal to the minimum number of nodes required to connect 15 edges, which is 8."},{"id":1837,"text":"If a train running at 72 km/h crosses a pole in 10 s, the length of train is:","options":[{"label":"A","text":"100 m"},{"label":"B","text":"150 m"},{"label":"C","text":"200 m"},{"label":"D","text":"250 m"}],"answer":2,"solution":"Speed = 72x(5/18) = 20 m/s. Length = 20x10 = 200 m."},{"id":1840,"text":"If x + y = 10 and xy = 21, then x^2 + y^2 is:","options":[{"label":"A","text":"100"},{"label":"B","text":"79"},{"label":"C","text":"58"},{"label":"D","text":"42"}],"answer":2,"solution":"x^2+y^2 = (x+y)^2 - 2xy = 100 - 42 = 58."},{"id":1846,"text":"The perimeter of a square is 40 cm. Its area is:","options":[{"label":"A","text":"80 cm^2"},{"label":"B","text":"160 cm^2"},{"label":"C","text":"100 cm^2"},{"label":"D","text":"200 cm^2"}],"answer":2,"solution":"Side = 40/4 = 10 cm. Area = 10^2 = 100 cm^2."},{"id":1850,"text":"Find the next term: 3, 9, 27, 81, ?","options":[{"label":"A","text":"162"},{"label":"B","text":"189"},{"label":"C","text":"243"},{"label":"D","text":"324"}],"answer":2,"solution":"Geometric progression with ratio 3: 3 = 243."},{"id":1854,"text":"If LOGIC is coded as 15-15-7-9-3, then what is the code for MATH?","options":[{"label":"A","text":"1-13-20-8"},{"label":"B","text":"13-1-20-8"},{"label":"C","text":"14-1-21-9"},{"label":"D","text":"12-1-19-7"}],"answer":2,"solution":"Each letter is coded as its position + 1. L(12)+3=15, O(15)+0=15, G(7)+0=7, I(9)+0=9, C(3)+0=3. For MATH: M(13)+1=14, A(1)+0=1, T(20)+1=21, H(8)+1=9 -> 14-1-21-9."},{"id":1857,"text":"Find the odd one out: 2, 4, 8, 16, 24, 32","options":[{"label":"A","text":"4"},{"label":"B","text":"8"},{"label":"C","text":"24"},{"label":"D","text":"32"}],"answer":2,"solution":"All others are powers of 2 (2, 2^2, 2, 2, 2). 24 is not a power of 2."},{"id":1861,"text":"A bat and a ball together cost $1.10. The bat costs $1.00 more than the ball. How much does the ball cost?","options":[{"label":"A","text":"$0.05"},{"label":"B","text":"$0.10"},{"label":"C","text":"$0.15"},{"label":"D","text":"$0.20"}],"answer":0,"solution":"Let's say the cost of the ball is x. Since the bat costs $1.00 more than the ball, the cost of the bat is x + $1.00. The total cost is $1.10, so we can set up the equation: x + (x + $1.00) = $1.10. Simplifying the equation, we get 2x + $1.00 = $1.10. Subtracting $1.00 from both sides, we get 2x = $0.10. Dividing both sides by 2, we get x = $0.05."},{"id":1873,"text":"Poisson's ratio for most metals is about:","options":[{"label":"A","text":"0.1"},{"label":"B","text":"0.3"},{"label":"C","text":"0.5"},{"label":"D","text":"1.0"}],"answer":1,"solution":"Poisson's ratio for metals: 0.25-0.35 (steel ~0.3). 0.5 for incompressible."},{"id":1877,"text":"What is the value of x in the equation 2^x + 2^x = 10?","options":[{"label":"A","text":"1"},{"label":"B","text":"2"},{"label":"C","text":"3"},{"label":"D","text":"4"}],"answer":1,"solution":"Given equation is 2^x + 2^x = 10, which can be simplified as 2 * 2^x = 10, then 2^x = 5. Since 2^2 = 4 and 2^3 = 8, the value of x that satisfies the equation is between 2 and 3, but closest to the given options is 2."},{"id":1880,"text":"The perimeter of a square is 40 cm. Its area is:","options":[{"label":"A","text":"80 cm^2"},{"label":"B","text":"160 cm^2"},{"label":"C","text":"100 cm^2"},{"label":"D","text":"200 cm^2"}],"answer":2,"solution":"Side = 40/4 = 10 cm. Area = 10^2 = 100 cm^2."},{"id":1886,"text":"If the radius of a circle is doubled, the area becomes:","options":[{"label":"A","text":"Double"},{"label":"B","text":"Four times"},{"label":"C","text":"Eight times"},{"label":"D","text":"Same"}],"answer":1,"solution":"A  r^2. If r -> 2r, A -> 4A."},{"id":1887,"text":"The number of diagonals in a pentagon is:","options":[{"label":"A","text":"3"},{"label":"B","text":"4"},{"label":"C","text":"5"},{"label":"D","text":"6"}],"answer":2,"solution":"n(n-3)/2 = 5(2)/2 = 5 diagonals."},{"id":1888,"text":"A car travels 60 km in 1.5 hours. Its average speed is:","options":[{"label":"A","text":"30 km/h"},{"label":"B","text":"40 km/h"},{"label":"C","text":"50 km/h"},{"label":"D","text":"90 km/h"}],"answer":1,"solution":"Speed = 60/1.5 = 40 km/h."},{"id":1893,"text":"If 3x + 2 = 11, then x = ?","options":[{"label":"A","text":"1"},{"label":"B","text":"3"},{"label":"C","text":"4"},{"label":"D","text":"2"}],"answer":1,"solution":"3x = 9 -> x = 3."},{"id":1895,"text":"The sum of ages of A and B is 45 years. 5 years from now, the ratio of their ages will be 4:5. Find the current age of A.","options":[{"label":"A","text":"15 years"},{"label":"B","text":"20 years"},{"label":"C","text":"25 years"},{"label":"D","text":"30 years"}],"answer":0,"solution":"Let A's age = x, B's age = 45-x. After 5 years: (x+5)/(50-x) = 4/5. 5x+25 = 200-4x. 9x = 175. x = 15."},{"id":1907,"text":"A train 150 m long passes a pole in 15 seconds. Find the speed of the train in km/h.","options":[{"label":"A","text":"12 km/h"},{"label":"B","text":"24 km/h"},{"label":"C","text":"36 km/h"},{"label":"D","text":"48 km/h"}],"answer":2,"solution":"Speed = distance/time = 150/15 = 10 m/s. In km/h: 10 x (18/5) = 36 km/h."},{"id":1911,"text":"If 5 men can build a wall in 12 days, how many days will 10 men take?","options":[{"label":"A","text":"24"},{"label":"B","text":"12"},{"label":"C","text":"6"},{"label":"D","text":"3"}],"answer":2,"solution":"MD = MD -> 5x12 = 10xD -> D = 6 days."},{"id":1914,"text":"If a train running at 72 km/h crosses a pole in 10 s, the length of train is:","options":[{"label":"A","text":"100 m"},{"label":"B","text":"150 m"},{"label":"C","text":"200 m"},{"label":"D","text":"250 m"}],"answer":2,"solution":"Speed = 72x(5/18) = 20 m/s. Length = 20x10 = 200 m."},{"id":1916,"text":"Find the missing number: 2, 6, 12, 20, ?","options":[{"label":"A","text":"28"},{"label":"B","text":"24"},{"label":"C","text":"30"},{"label":"D","text":"36"}],"answer":2,"solution":"Pattern: 1x2=2, 2x3=6, 3x4=12, 4x5=20, 5x6=30."},{"id":1926,"text":"If 15 workers can build a wall in 8 days, how many workers are needed to build same wall in 6 days?","options":[{"label":"A","text":"12"},{"label":"B","text":"18"},{"label":"C","text":"20"},{"label":"D","text":"25"}],"answer":2,"solution":"MD = MD -> 15x8 = Mx6 -> M = 20."},{"id":1927,"text":"If x + y = 10 and xy = 21, then x^2 + y^2 is:","options":[{"label":"A","text":"100"},{"label":"B","text":"79"},{"label":"C","text":"58"},{"label":"D","text":"42"}],"answer":2,"solution":"x^2+y^2 = (x+y)^2 - 2xy = 100 - 42 = 58."},{"id":1930,"text":"A man buys a book for 500 and sells it for 600. Profit percentage is:","options":[{"label":"A","text":"10%"},{"label":"B","text":"20%"},{"label":"C","text":"15%"},{"label":"D","text":"25%"}],"answer":1,"solution":"Profit = 100, CP = 500. Profit% = 100/500 x 100 = 20%."},{"id":1933,"text":"Choose the correct spelling:","options":[{"label":"A","text":"Mischeivous"},{"label":"B","text":"Mischievious"},{"label":"C","text":"Mischievous"},{"label":"D","text":"Mischevous"}],"answer":2,"solution":"Correct spelling: Mischievous."},{"id":1934,"text":"The simple interest on 1000 at 5% per annum for 2 years is:","options":[{"label":"A","text":"50"},{"label":"B","text":"100"},{"label":"C","text":"200"},{"label":"D","text":"25"}],"answer":1,"solution":"SI = PxRxT/100 = 1000x5x2/100 = 100."}]},{"name":"Structural","count":8,"questions":[{"id":1658,"text":"The unit of moment of inertia is:","options":[{"label":"A","text":"N/m"},{"label":"B","text":"kg/m²"},{"label":"C","text":"m4"},{"label":"D","text":"N·m"}],"answer":2,"solution":"Moment of inertia (area) has units of m4."},{"id":1659,"text":"A simply supported beam with UDL has maximum bending moment at:","options":[{"label":"A","text":"Ends"},{"label":"B","text":"Mid-span"},{"label":"C","text":"Quarter span"},{"label":"D","text":"Supports"}],"answer":1,"solution":"Mmax = wL²/8 at mid-span for simply supported beam with UDL."},{"id":1660,"text":"The factor of safety is defined as:","options":[{"label":"A","text":"Ultimate load/Working load"},{"label":"B","text":"Ultimate strength/Working stress"},{"label":"C","text":"Yield stress/Working stress"},{"label":"D","text":"Both A and B"}],"answer":1,"solution":"FoS = ultimate load / allowable load = ultimate stress / working stress."},{"id":1661,"text":"The Euler's buckling load for a column depends on:","options":[{"label":"A","text":"Material only"},{"label":"B","text":"Length only"},{"label":"C","text":"Length, E, I, and end conditions"},{"label":"D","text":"Cross-section only"}],"answer":2,"solution":"Pcr = p²EI/(Le)². Depends on E, I, effective length (end conditions)."},{"id":1662,"text":"Concrete is strong in:","options":[{"label":"A","text":"Tension"},{"label":"B","text":"Compression"},{"label":"C","text":"Shear"},{"label":"D","text":"Torsion"}],"answer":1,"solution":"Concrete has high compressive strength but low tensile strength (reinforced with steel)."},{"id":1673,"text":"The grade of concrete M20 means:","options":[{"label":"A","text":"20 kN/m³ density"},{"label":"B","text":"20 MPa compressive strength"},{"label":"C","text":"20 N/mm² tensile strength"},{"label":"D","text":"20% water content"}],"answer":1,"solution":"M20 = 20 MPa (20 N/mm²) characteristic compressive strength at 28 days."},{"id":1676,"text":"Slab spanning in one direction only is called:","options":[{"label":"A","text":"Two-way slab"},{"label":"B","text":"One-way slab"},{"label":"C","text":"Flat slab"},{"label":"D","text":"Ribbed slab"}],"answer":1,"solution":"One-way slab: L/B = 2, main reinforcement in shorter span direction."},{"id":1679,"text":"The effective span of a simply supported beam is:","options":[{"label":"A","text":"Clear span"},{"label":"B","text":"Center to center of supports"},{"label":"C","text":"Clear span + effective depth"},{"label":"D","text":"Overall length"}],"answer":2,"solution":"For simply supported: Le = min(Lc + d, c/c distance of supports)."}]},{"name":"Analog","count":8,"questions":[{"id":1723,"text":"An ideal op-amp has infinite:","options":[{"label":"A","text":"Output impedance"},{"label":"B","text":"Input impedance"},{"label":"C","text":"Bandwidth"},{"label":"D","text":"Both Band C"}],"answer":1,"solution":"Ideal op-amp: infinite input impedance, zero output impedance, infinite gain."},{"id":1724,"text":"A diode in forward bias has:","options":[{"label":"A","text":"High resistance"},{"label":"B","text":"Low resistance"},{"label":"C","text":"Infinite resistance"},{"label":"D","text":"Zero current"}],"answer":1,"solution":"Forward bias: diode conducts with low resistance (~0.7 V drop for Si)."},{"id":1725,"text":"A transistor has three terminals: base, collector, and:","options":[{"label":"A","text":"Gate"},{"label":"B","text":"Drain"},{"label":"C","text":"Emitter"},{"label":"D","text":"Source"}],"answer":2,"solution":"BJT terminals: Base, Collector, Emitter. FET: Gate, Drain, Source."},{"id":1726,"text":"The purpose of a heat sink in power amplifiers is to:","options":[{"label":"A","text":"Increase gain"},{"label":"B","text":"Reduce distortion"},{"label":"C","text":"Dissipate heat"},{"label":"D","text":"Increase bandwidth"}],"answer":2,"solution":"Heat sink dissipates excess heat from power transistors to prevent thermal damage."},{"id":1727,"text":"The gain of an on-inverting amplifier with Rf=10 kO and R1=1 kO is:","options":[{"label":"A","text":"10"},{"label":"B","text":"11"},{"label":"C","text":"9"},{"label":"D","text":"1"}],"answer":1,"solution":"Gain = 1 + Rf/R1 = 1 + 10 = 11."},{"id":1728,"text":"A Zener diode is used for:","options":[{"label":"A","text":"Rectification"},{"label":"B","text":"Amplification"},{"label":"C","text":"Voltage regulation"},{"label":"D","text":"Switching"}],"answer":2,"solution":"Zener diode maintains constant voltage in reverse breakdown → voltage regulator."},{"id":1736,"text":"The bandwidth of an ideal bandpass filter is:","options":[{"label":"A","text":"Zero"},{"label":"B","text":"Equal to center frequency"},{"label":"C","text":"Difference of cut-off frequencies"},{"label":"D","text":"Infinite"}],"answer":2,"solution":"BW = fH - fL where fH and flare upper and lower cut-off frequencies."},{"id":1740,"text":"Class A amplifier has conduction angle of:","options":[{"label":"A","text":"90°"},{"label":"B","text":"180°"},{"label":"C","text":"360°"},{"label":"D","text":"270°"}],"answer":2,"solution":"Class A: conducts for full 360° of input cycle → low efficiency (~25%)."}]},{"name":"Thermodynamics","count":8,"questions":[{"id":1748,"text":"The SI unit of thermal conductivity is:","options":[{"label":"A","text":"W/m"},{"label":"B","text":"W/mK"},{"label":"C","text":"J/kgK"},{"label":"D","text":"N/m²"}],"answer":1,"solution":"Thermal conductivity k: W/(m·K)."},{"id":1749,"text":"The efficiency of Carnot cycle depends on:","options":[{"label":"A","text":"Working fluid"},{"label":"B","text":"Temperature limits"},{"label":"C","text":"Pressure ratio"},{"label":"D","text":"Engine size"}],"answer":1,"solution":"η = 1 - T2/T1 (depends only on source and sink temperatures)."},{"id":1750,"text":"In an isothermal process, which quantity remains constant?","options":[{"label":"A","text":"Pressure"},{"label":"B","text":"Volume"},{"label":"C","text":"Temperature"},{"label":"D","text":"Entropy"}],"answer":2,"solution":"Isothermal: T = constant, PV = constant (for ideal gas)."},{"id":1751,"text":"The unit of entropy is:","options":[{"label":"A","text":"J/K"},{"label":"B","text":"kJ/K"},{"label":"C","text":"kJ/kgK"},{"label":"D","text":"All of these"}],"answer":1,"solution":"Entropy units: J/K (total) or kJ/kg·K (specific)."},{"id":1752,"text":"The first law of thermodynamics is essentially:","options":[{"label":"A","text":"Conservation of mass"},{"label":"B","text":"Conservation of energy"},{"label":"C","text":"Conservation of momentum"},{"label":"D","text":"Law of entropy"}],"answer":1,"solution":"ΔU = Q - W (energy conservation for thermodynamic systems)."},{"id":1763,"text":"A heat engine rejects 300 J to sink while doing 200 J work. Heat supplied is:","options":[{"label":"A","text":"100 J"},{"label":"B","text":"300 J"},{"label":"C","text":"500 J"},{"label":"D","text":"600 J"}],"answer":2,"solution":"Q1 = W + Q2 = 200 + 300 = 500 J."},{"id":1766,"text":"The COP of a refrigerator is 4. If it extracts 200 J from cold reservoir, work input is:","options":[{"label":"A","text":"20 J"},{"label":"B","text":"40 J"},{"label":"C","text":"50 J"},{"label":"D","text":"200 J"}],"answer":2,"solution":"COP = Q2/W ⇒ 4 = 200/W ⇒ W = 50 J."},{"id":1770,"text":"The Otto cycle efficiency increases with:","options":[{"label":"A","text":"Decrease in compression ratio"},{"label":"B","text":"Increase in compression ratio"},{"label":"C","text":"Increase in specific heat"},{"label":"D","text":"Decrease in temperature"}],"answer":1,"solution":"η = 1 - 1/r^(γ-1). Higher compression ratio → higher efficiency."}]},{"name":"Water","count":7,"questions":[{"id":1668,"text":"The unit of hydraulic gradient is:","options":[{"label":"A","text":"m"},{"label":"B","text":"m/s"},{"label":"C","text":"Dimensionless"},{"label":"D","text":"m²/s"}],"answer":2,"solution":"Hydraulic gradient i = h/L (head loss / length) — dimensionless."},{"id":1669,"text":"Bernoulli's equation is based on:","options":[{"label":"A","text":"Conservation of mass"},{"label":"B","text":"Conservation of momentum"},{"label":"C","text":"Conservation of energy"},{"label":"D","text":"Continuity"}],"answer":2,"solution":"P/ρg + v²/2g + z = constant (energy per unit weight)."},{"id":1670,"text":"The Chezy'sco efficient C in Manning's formula relates to:","options":[{"label":"A","text":"Channel roughness"},{"label":"B","text":"Channel depth"},{"label":"C","text":"Both roughness and hydraulic radius"},{"label":"D","text":"Discharge"}],"answer":2,"solution":"Manning: V = (1/n)R^(2/3)S^(1/2). Chezy: C = (1/n)R^(1/6)."},{"id":1671,"text":"The optimum depth of a canal is when:","options":[{"label":"A","text":"Width is minimum"},{"label":"B","text":"Hydraulic radius is maximum"},{"label":"C","text":"Wetted perimeter is maximum"},{"label":"D","text":"Velocity is minimum"}],"answer":1,"solution":"Most economical section: max hydraulic radius → min wetted perimeter."},{"id":1672,"text":"The pH of pure water is:","options":[{"label":"A","text":"0"},{"label":"B","text":"14"},{"label":"C","text":"7"},{"label":"D","text":"10"}],"answer":2,"solution":"Pure water has pH 7 at 25°C (neutral)."},{"id":1675,"text":"The Manning's roughness coefficient n for concrete is about:","options":[{"label":"A","text":"0.001"},{"label":"B","text":"0.035"},{"label":"C","text":"0.013"},{"label":"D","text":"0.1"}],"answer":2,"solution":"Manning's n for concrete: 0.012-0.015 (typically 0.013)."},{"id":1680,"text":"The total hardness of water is due to:","options":[{"label":"A","text":"Na⁺ and K⁺"},{"label":"B","text":"Ca²⁺ and Mg²⁺"},{"label":"C","text":"Cl⁻ and SO4²⁻"},{"label":"D","text":"Fe²⁺ and Mn²⁺"}],"answer":1,"solution":"Hardness: Ca²⁺ and Mg²⁺ ions (temporary: bicarbonates, permanent: sulfates/chlorides)."}]},{"name":"Networks","count":7,"questions":[{"id":1718,"text":"Thevenin's theorem is used to simplify:","options":[{"label":"A","text":"Non-linear circuits"},{"label":"B","text":"Linear circuits"},{"label":"C","text":"Digital circuits"},{"label":"D","text":"Magnetic circuits"}],"answer":1,"solution":"Thevenin's theorem applies to linear circuits (voltage source + series resistance)."},{"id":1719,"text":"In an RC circuit, the time constant is:","options":[{"label":"A","text":"R + C"},{"label":"B","text":"RC"},{"label":"C","text":"R/C"},{"label":"D","text":"C/R"}],"answer":1,"solution":"t = RC (time for voltage to reach 63.2% of final value)."},{"id":1720,"text":"Kirchhoff's current law is based on:","options":[{"label":"A","text":"Conservation of energy"},{"label":"B","text":"Conservation of charge"},{"label":"C","text":"Ohm's law"},{"label":"D","text":"Faraday's law"}],"answer":1,"solution":"KCL: sum of currents entering = sum leaving (charge conservation)."},{"id":1721,"text":"The impedance of a capacitor of capacitance C at frequency ω is:","options":[{"label":"A","text":"jωC"},{"label":"B","text":"1/(jωC)"},{"label":"C","text":"ωC"},{"label":"D","text":"1/(ωC)"}],"answer":1,"solution":"Zc = 1/(jωC) = -j/(ωC)."},{"id":1722,"text":"The power dissipated in a resistor R with current I is:","options":[{"label":"A","text":"IR"},{"label":"B","text":"I²R"},{"label":"C","text":"V²R"},{"label":"D","text":"IR²"}],"answer":1,"solution":"P = I²R = V²/R = VI."},{"id":1735,"text":"The RMS value of sinusoidal voltage v = 10 sin(ωt) is:","options":[{"label":"A","text":"10 V"},{"label":"B","text":"7.07 V"},{"label":"C","text":"5 V"},{"label":"D","text":"14.14 V"}],"answer":1,"solution":"Vrms = Vm/v2 = 10/1.414 = 7.07 V."},{"id":1737,"text":"Two 10 Ω resistors in parallel give equivalent resistance:","options":[{"label":"A","text":"20 Ω"},{"label":"B","text":"5 Ω"},{"label":"C","text":"10 Ω"},{"label":"D","text":"2.5 Ω"}],"answer":1,"solution":"1/Rp = 1/10 + 1/10 = 2/10 ⇒ Rp = 5 Ω."}]},{"name":"Digital","count":7,"questions":[{"id":1729,"text":"Binary equivalent of decimal 15 is:","options":[{"label":"A","text":"1010"},{"label":"B","text":"1100"},{"label":"C","text":"1111"},{"label":"D","text":"1001"}],"answer":2,"solution":"15 = 8+4+2+1 = 11112."},{"id":1730,"text":"Which flip-flop has no race condition?","options":[{"label":"A","text":"SR"},{"label":"B","text":"JK"},{"label":"C","text":"Master-slave JK"},{"label":"D","text":"D"}],"answer":2,"solution":"Master-slave JK flip-flop eliminates race-around condition."},{"id":1731,"text":"How many AND gates are needed for 8-to-1 multiplexer?","options":[{"label":"A","text":"4"},{"label":"B","text":"6"},{"label":"C","text":"8"},{"label":"D","text":"16"}],"answer":2,"solution":"8-to-1 MUX needs 8 AND gates (one per input) + 1 OR gate."},{"id":1732,"text":"The number of input lines for 3-to-8 decoder is:","options":[{"label":"A","text":"8"},{"label":"B","text":"2"},{"label":"C","text":"3"},{"label":"D","text":"4"}],"answer":2,"solution":"3-to-8 decoder: 3 inputs, 8 outputs."},{"id":1733,"text":"The output of XOR gate with inputs (1,1) is:","options":[{"label":"A","text":"1"},{"label":"B","text":"0"},{"label":"C","text":"High impedance"},{"label":"D","text":"Don't care"}],"answer":1,"solution":"XOR: output 1 when inputs differ, 0 when same. 1⊕1 = 0."},{"id":1734,"text":"A counter with 4 flip-flops can count up to:","options":[{"label":"A","text":"8"},{"label":"B","text":"16"},{"label":"C","text":"4"},{"label":"D","text":"32"}],"answer":1,"solution":"4-bit counter: 24 = 16 states (0 to 15)."},{"id":1738,"text":"A 4-bit R-2R DAC uses resistors of values:","options":[{"label":"A","text":"Only R"},{"label":"B","text":"Only 2R"},{"label":"C","text":"Rand 2R"},{"label":"D","text":"R, 2R, 4R"}],"answer":2,"solution":"R-2R ladder DAC uses only Rand 2R resistors for binary-weighted conversion."}]},{"name":"Strength of Materials","count":7,"questions":[{"id":1753,"text":"Hooke's law states that stress is proportional to:","options":[{"label":"A","text":"Force"},{"label":"B","text":"Strain"},{"label":"C","text":"Area"},{"label":"D","text":"Length"}],"answer":1,"solution":"Within elastic limit, s ∝ e (stress ∝ strain)."},{"id":1754,"text":"Poisson's ratio for most metals is about:","options":[{"label":"A","text":"0.1"},{"label":"B","text":"0.3"},{"label":"C","text":"0.5"},{"label":"D","text":"1.0"}],"answer":1,"solution":"Poisson's ratio for metals: 0.25-0.35 (steel ~0.3). 0.5 for incompressible."},{"id":1755,"text":"The bending moment at a simply supported beam's center with point load P at center is:","options":[{"label":"A","text":"PL/2"},{"label":"B","text":"PL/4"},{"label":"C","text":"PL/8"},{"label":"D","text":"PL"}],"answer":1,"solution":"Mmax = PL/4 for simply supported beam with central point load."},{"id":1757,"text":"A material that undergoes large deformation before fracture is called:","options":[{"label":"A","text":"Brittle"},{"label":"B","text":"Ductile"},{"label":"C","text":"Elastic"},{"label":"D","text":"Plastic"}],"answer":1,"solution":"Ductile materials (steel, aluminum) undergo significant plastic deformation before fracture."},{"id":1764,"text":"The modulus of rigidity relates shear stress to:","options":[{"label":"A","text":"Normal strain"},{"label":"B","text":"Shear strain"},{"label":"C","text":"Volumetric strain"},{"label":"D","text":"Lateral strain"}],"answer":1,"solution":"G = τ/γ (shear stress / shear strain)."},{"id":1768,"text":"A steel rod of 10 mm diameter carries 31.4 kN load. Stress is:","options":[{"label":"A","text":"100 MPa"},{"label":"B","text":"200 MPa"},{"label":"C","text":"400 MPa"},{"label":"D","text":"314 MPa"}],"answer":2,"solution":"A = p(0.01)²/4 = 7.85×10⁻⁵ m². s = 31400/7.85e-5 = 400 MPa."},{"id":1771,"text":"Beam deflection is maximum at:","options":[{"label":"A","text":"Supports"},{"label":"B","text":"Point of load"},{"label":"C","text":"Depends on loading"},{"label":"D","text":"Center always"}],"answer":2,"solution":"Deflection depends on loading type. For UDL: max at center. For point load: at load point."}]},{"name":"Production","count":7,"questions":[{"id":1758,"text":"Which process is used to make threads on a bolt?","options":[{"label":"A","text":"Milling"},{"label":"B","text":"Drilling"},{"label":"C","text":"Threading"},{"label":"D","text":"Grinding"}],"answer":2,"solution":"Threading (using dies) cuts external threads on bolts and rods."},{"id":1759,"text":"TIG welding uses which electrode?","options":[{"label":"A","text":"Consumable"},{"label":"B","text":"Non-consumable tungsten"},{"label":"C","text":"Copper"},{"label":"D","text":"Steel"}],"answer":1,"solution":"TIG (Tungsten Inert Gas) uses non-consumable tungsten electrode."},{"id":1760,"text":"The cutting speed in a lathe is measured in:","options":[{"label":"A","text":"RPM"},{"label":"B","text":"m/min"},{"label":"C","text":"mm/rev"},{"label":"D","text":"mm"}],"answer":1,"solution":"Cutting speed = pDN/1000 m/min (D in mm, N in RPM)."},{"id":1761,"text":"Which casting process uses a wax pattern?","options":[{"label":"A","text":"Sand casting"},{"label":"B","text":"Die casting"},{"label":"C","text":"Investment casting"},{"label":"D","text":"Centrifugal casting"}],"answer":2,"solution":"Investment (lost wax) casting: wax pattern coated with ceramic, melted out, metal poured."},{"id":1762,"text":"The operation of enlarging a hole is called:","options":[{"label":"A","text":"Drilling"},{"label":"B","text":"Reaming"},{"label":"C","text":"Boring"},{"label":"D","text":"Counter-sinking"}],"answer":2,"solution":"Boring enlarges an existing hole. Reaming gives smooth finish."},{"id":1765,"text":"In orthogonal cutting, the cutting edge is:","options":[{"label":"A","text":"Parallel to work surface"},{"label":"B","text":"Perpendicular to cutting velocity"},{"label":"C","text":"At 45°"},{"label":"D","text":"Inclined"}],"answer":1,"solution":"Orthogonal cutting: cutting edge ⊥ to cutting velocity direction."},{"id":1769,"text":"The material used for cutting tools is:","options":[{"label":"A","text":"Mild steel"},{"label":"B","text":"HSS (High Speed Steel)"},{"label":"C","text":"Cast iron"},{"label":"D","text":"Brass"}],"answer":1,"solution":"HSS retains hardness at high cutting temperatures (used for drills, end mills)."}]},{"name":"Geotechnical","count":6,"questions":[{"id":1665,"text":"The bearing capacity of soil is improved by:","options":[{"label":"A","text":"Water addition"},{"label":"B","text":"Compaction"},{"label":"C","text":"Excavation"},{"label":"D","text":"Aeration"}],"answer":1,"solution":"Compaction increases soil density → higher bearing capacity."},{"id":1666,"text":"The standard penetration test (SPT) N-value indicates:","options":[{"label":"A","text":"Water content"},{"label":"B","text":"Soil density/strength"},{"label":"C","text":"Permeability"},{"label":"D","text":"Plasticity"}],"answer":1,"solution":"SPT N-value correlates with relative density and strength of soil."},{"id":1667,"text":"Darcy's law governs the flow of water through:","options":[{"label":"A","text":"Pipes"},{"label":"B","text":"Open channels"},{"label":"C","text":"Porous media"},{"label":"D","text":"Rivers"}],"answer":2,"solution":"v = ki (Darcy's law for flow through porous media like soil)."},{"id":1674,"text":"Quick sand condition occurs when:","options":[{"label":"A","text":"Permeability is zero"},{"label":"B","text":"Upward seepage force equals submerged weight"},{"label":"C","text":"Soil is fully dry"},{"label":"D","text":"Water table is low"}],"answer":1,"solution":"Quicksand: upward hydraulic gradient = critical gradient (ic = Gs-1)/(1+e)."},{"id":1678,"text":"The dry density of soil is maximum at:","options":[{"label":"A","text":"Liquid limit"},{"label":"B","text":"Plastic limit"},{"label":"C","text":"Optimum moisture content"},{"label":"D","text":"Shrinkage limit"}],"answer":2,"solution":"Proctor test: maximum dry density at OMC (optimum moisture content)."},{"id":1681,"text":"The plasticity chart classifies soil based on:","options":[{"label":"A","text":"Grain size"},{"label":"B","text":"Liquid limit and plasticity index"},{"label":"C","text":"Permeability"},{"label":"D","text":"Compaction"}],"answer":1,"solution":"Casagrande's plasticity chart: LL vs PI to classify fine-grained soils (CL, CH, ML, MH)."}]},{"name":"Theory of Computation","count":6,"questions":[{"id":1690,"text":"A language accepted by a Finite Automaton is called:","options":[{"label":"A","text":"Regular language"},{"label":"B","text":"Context-free language"},{"label":"C","text":"Context-sensitive language"},{"label":"D","text":"Recursively enumerable language"}],"answer":0,"solution":"Finite automata accept exactly the class of regular languages (Type 3 in Chomsky hierarchy)."},{"id":1691,"text":"Which of the following is NOT a valid Boolean algebra property?","options":[{"label":"A","text":"A · 0 = 0"},{"label":"B","text":"A + 1 = 1"},{"label":"C","text":"A · A = A"},{"label":"D","text":"A + A = 0"}],"answer":3,"solution":"A + A = A (idempotent law), not 0. A + A¯ = 1 and A · A¯ = 0."},{"id":1695,"text":"Which of the following problems is undecidable?","options":[{"label":"A","text":"Checking if a DFA accepts a given string"},{"label":"B","text":"Checking if a CFL is empty"},{"label":"C","text":"The Halting Problem for Turing Machines"},{"label":"D","text":"Checking if an NFA accepts a given string"}],"answer":2,"solution":"The Halting Problem is undecidable (proved by Alan Turing). All other options are decidable."},{"id":1706,"text":"Which language is accepted by Pushdown Automata?","options":[{"label":"A","text":"Regular"},{"label":"B","text":"Context-Free"},{"label":"C","text":"Context-Sensitive"},{"label":"D","text":"Recursively Enumerable"}],"answer":1,"solution":"PDA accepts exactly the class of Context-Free Languages (CFL)."},{"id":1707,"text":"If Land ¬L are both recursively enumerable, then L is:","options":[{"label":"A","text":"Regular"},{"label":"B","text":"Context-Free"},{"label":"C","text":"Recursive"},{"label":"D","text":"Not recursively enumerable"}],"answer":2,"solution":"If Land its complement are both RE, then L is recursive (decidable)."},{"id":1711,"text":"Which of the following is a universal gate?","options":[{"label":"A","text":"AND"},{"label":"B","text":"OR"},{"label":"C","text":"NOT"},{"label":"D","text":"NAND"}],"answer":3,"solution":"NAND and NOR are universal gates — any Boolean function can be implemented using only NAND (or only NOR) gates."}]},{"name":"DS & Algorithms","count":5,"questions":[{"id":1696,"text":"The worst-case time complexity of quicksort is:","options":[{"label":"A","text":"O(log n)"},{"label":"B","text":"O(n log n)"},{"label":"C","text":"O(n²)"},{"label":"D","text":"O(n)"}],"answer":2,"solution":"Quicksort worst-case O(n²) when pivot is smallest/largest element (e.g., sorted array with naive pivot)."},{"id":1699,"text":"Which of the following is a linear data structure?","options":[{"label":"A","text":"Tree"},{"label":"B","text":"Queue"},{"label":"C","text":"Graph"},{"label":"D","text":"Binary Tree"}],"answer":1,"solution":"Queue is linear (elements in sequence). Tree and Graph aren on-linear data structures."},{"id":1700,"text":"The height of a complete binary tree with nno des is:","options":[{"label":"A","text":"n"},{"label":"B","text":"n/2"},{"label":"C","text":"⌊log₂ n⌋"},{"label":"D","text":"vn"}],"answer":2,"solution":"Height of a complete binary tree with nno des is ⌊log₂ n⌋."},{"id":1701,"text":"In am in-heap, the smallest element is at:","options":[{"label":"A","text":"Root"},{"label":"B","text":"Leftmost leaf"},{"label":"C","text":"Rightmost leaf"},{"label":"D","text":"Last node"}],"answer":0,"solution":"Min-heap property: parent = children, so root is always the minimum element."},{"id":1708,"text":"Which traversal gives sorted order in a BST?","options":[{"label":"A","text":"Preorder"},{"label":"B","text":"Postorder"},{"label":"C","text":"Inorder"},{"label":"D","text":"Level order"}],"answer":2,"solution":"Inorder traversal of BST visits nodes in ascending order (left → root → right)."}]},{"name":"Data Structures & Algorithms","count":4,"questions":[{"id":1684,"text":"What is the time complexity of binary search on a sorted array of n elements?","options":[{"label":"A","text":"O(n)"},{"label":"B","text":"O(log n)"},{"label":"C","text":"O(n²)"},{"label":"D","text":"O(n log n)"}],"answer":1,"solution":"Binary search divides the search space in half each iteration, giving O(log n) time complexity."},{"id":1685,"text":"A stack is implemented using an array. If the top pointer is at index 5, what is the current size of the stack?","options":[{"label":"A","text":"6"},{"label":"B","text":"5"},{"label":"C","text":"4"},{"label":"D","text":"7"}],"answer":0,"solution":"If top = 5 (0-indexed), there are 6 elements at indices 0 through 5."},{"id":1686,"text":"Which data structure is used for implementing recursion?","options":[{"label":"A","text":"Queue"},{"label":"B","text":"Array"},{"label":"C","text":"Stack"},{"label":"D","text":"Linked List"}],"answer":2,"solution":"Recursion uses the call stack (LIFO) to store function call frames and return addresses."},{"id":1692,"text":"What does the following C expression evaluate to? (Assume i = 5) i++ + ++i","options":[{"label":"A","text":"10"},{"label":"B","text":"11"},{"label":"C","text":"12"},{"label":"D","text":"Undefined"}],"answer":2,"solution":"i++ uses current value (5) then increments to 6. ++i increments to 7 then uses 7. So 5 + 7 = 12."}]},{"name":"Computer Organization & OS","count":4,"questions":[{"id":1687,"text":"Which memory has the fastest access time?","options":[{"label":"A","text":"RAM"},{"label":"B","text":"Cache"},{"label":"C","text":"Hard Disk"},{"label":"D","text":"SSD"}],"answer":1,"solution":"Cache memory is closest to the CPU and has the fastest access time (nanoseconds), followed by RAM, then SSD, then HDD."},{"id":1688,"text":"Which scheduling algorithm is non-preemptive?","options":[{"label":"A","text":"Round Robin"},{"label":"B","text":"FCFS"},{"label":"C","text":"Shortest Remaining Time First"},{"label":"D","text":"Priority (Preemptive)"}],"answer":1,"solution":"First Come First Serve (FCFS) is non-preemptive — once a process gets the CPU, it runs until completion or I/O."},{"id":1689,"text":"The main function of an operating system is:","options":[{"label":"A","text":"Compiling programs"},{"label":"B","text":"Providing internet access"},{"label":"C","text":"Managing hardware resources"},{"label":"D","text":"Running applications"}],"answer":2,"solution":"The Osman ages CPU, memory, I/Ode vices, and provides resource allocation and protection."},{"id":1693,"text":"In virtual memory, which technique is used for address translation?","options":[{"label":"A","text":"Segmentation"},{"label":"B","text":"Compaction"},{"label":"C","text":"Paging"},{"label":"D","text":"Swapping"}],"answer":2,"solution":"Paging maps virtual addresses to physical addresses using page tables, enabling virtual memory."}]},{"name":"CO & OS","count":4,"questions":[{"id":1702,"text":"Which of the following is a volatile memory?","options":[{"label":"A","text":"ROM"},{"label":"B","text":"Hard disk"},{"label":"C","text":"RAM"},{"label":"D","text":"Flash drive"}],"answer":2,"solution":"RAM (Random Access Memory) is volatile — data is lost when power is turned off."},{"id":1703,"text":"The number of bits in a nibble is:","options":[{"label":"A","text":"2"},{"label":"B","text":"4"},{"label":"C","text":"8"},{"label":"D","text":"16"}],"answer":1,"solution":"1 nibble = 4 bits. 1 byte = 2 nibbles = 8 bits."},{"id":1704,"text":"Which of the following is NOT an operating system?","options":[{"label":"A","text":"Windows"},{"label":"B","text":"Linux"},{"label":"C","text":"Python"},{"label":"D","text":"macOS"}],"answer":2,"solution":"Python is a programming language, not an operating system."},{"id":1710,"text":"A semaphore that is used as a binary lock is called:","options":[{"label":"A","text":"Counting semaphore"},{"label":"B","text":"Mutex"},{"label":"C","text":"Spinlock"},{"label":"D","text":"Monitor"}],"answer":1,"solution":"Mutex (mutual exclusion) is a binary semaphore used for locking in concurrent programming."}]},{"name":"Engineering Mathematics","count":4,"questions":[{"id":1865,"text":"What is the determinant of the matrix [1, 2; 3, 4]?","options":[{"label":"A","text":"-2"},{"label":"B","text":"2"},{"label":"C","text":"-1"},{"label":"D","text":"1"}],"answer":0,"solution":"The determinant of a 2x2 matrix [a, b; c, d] is given by ad - bc. In this case, the determinant is (1)(4) - (2)(3) = 4 - 6 = -2."},{"id":1889,"text":"What is the value of the integral of x^2 dx from 0 to 2?","options":[{"label":"A","text":"2/3"},{"label":"B","text":"8/3"},{"label":"C","text":"4/3"},{"label":"D","text":"16/3"}],"answer":1,"solution":"The integral of x^2 dx from 0 to 2 is (1/3)x^3 from 0 to 2, which is (1/3)(2^3) - (1/3)(0^3) = (1/3)(8) = 8/3."},{"id":1900,"text":"What is the value of the eigenvalue of the matrix [2, 1; 1, 2]?","options":[{"label":"A","text":"1"},{"label":"B","text":"3"},{"label":"C","text":"-1"},{"label":"D","text":"-3"}],"answer":1,"solution":"The characteristic equation of the matrix [2, 1; 1, 2] is |A - λI| = 0, where λ is the eigenvalue. Expanding the determinant, we get (2 - λ)(2 - λ) - 1 = 0, which simplifies to λ^2 - 4λ + 3 = 0. Solving the quadratic equation, we get λ = 1 and λ = 3. Therefore, the eigenvalue of the matrix is 3."},{"id":1904,"text":"What is the order of the differential equation d^2y/dx^2 + 3dy/dx + 2y = 0?","options":[{"label":"A","text":"1"},{"label":"B","text":"2"},{"label":"C","text":"3"},{"label":"D","text":"4"}],"answer":1,"solution":"The order of a differential equation is determined by the highest order derivative. In this case, the highest order derivative is d^2y/dx^2, which is of order 2."}]}]};